const job = $input.first().json;
const payload = job.payload;

const config = {
  workspaceId: "__SLACK_WORKSPACE_ID__",
  sourceChannelId: "__SLACK_REQUESTS_CHANNEL_ID__",
  approvalChannelId: "__SLACK_APPROVALS_CHANNEL_ID__",
  reviewChannelId: "__SLACK_REVIEW_CHANNEL_ID__"
};

if (
  job.status !== "processing" ||
  !job.lease_token ||
  !(Date.parse(job.leased_until) > Date.now())
) {
  throw new Error("Notification lease is missing or expired");
}

if (
  !payload ||
  payload.workspace_id !== config.workspaceId ||
  payload.channel_id !== config.sourceChannelId ||
  String(payload.message_id) !== String(job.message_id)
) {
  throw new Error("Notification source is not allowed");
}

if (
  !/^[UW][A-Z0-9]+$/.test(payload.author_id || "") ||
  !/^\d+$/.test(String(job.message_id))
) {
  throw new Error("Invalid notification identity");
}

const requests = payload.requests;

if (
  !Array.isArray(requests) ||
  requests.some(r => !r || typeof r !== "object" || Array.isArray(r))
) {
  throw new Error("Invalid notification requests");
}

function value(input) {
  if (input === null || input === undefined || input === "") {
    return "Not specified";
  }

  return String(input)
    .replace(/[\u0000-\u001F\u007F]/g, " ")
    .trim();
}

function field(label, input) {
  const text = `${label}: ${value(input)}`;

  return {
    type: "plain_text",
    text: text.length > 1800
      ? `${text.slice(0, 1750)}… [truncated]`
      : text,
    emoji: false
  };
}

const resourceNames = {
  postgres: "PostgreSQL",
  grafana: "Grafana"
};

const permissionNames = {
  viewer: "Viewer",
  read_only: "Read only",
  write: "Write",
  admin: "Administrator",
  root: "Root",
  owner: "Owner"
};

const environmentNames = {
  development: "Development",
  staging: "Staging",
  production: "Production"
};

const riskNames = {
  production_mentioned: "Production mentioned in the message",
  production_access: "Production access",
  privileged_permissions_mentioned: "Privileged permissions mentioned",
  elevated_permissions: "Elevated permissions",
  environment_not_allowed: "Outside the standard approval policy",
  permission_not_allowed: "Outside the standard approval policy",
  instruction_attempt: "Attempt to override extraction instructions",
  sensitive_data_detected: "Sensitive data detected",
  unknown_resource: "Resource is outside the supported catalog",
  duration_exceeds_7_days: "Access duration exceeds seven days",
  beneficiary_requires_verification: "Beneficiary identity requires verification",
  message_too_long: "Message exceeds the processing limit",
  thread_context_truncated: "Thread history is incomplete",
  multiple_pending_requests: "Multiple pending requests in the thread",
  invalid_thread_target: "Thread update target could not be verified",
  conflicting_thread_update: "Reply conflicts with existing request details",
  inconsistent_llm_output: "Extraction result is inconsistent",
  empty_access_request: "Extraction returned no request details",
  llm_processing_failed: "Automatic extraction failed"
};

const titles = {
  clarification: "💬 More details needed",
  standard_approval: "📝 Access approval required",
  manual_review: "⚠️ DevOps review required"
};

const title = titles[job.kind];

if (!title) {
  throw new Error("Unknown notification kind");
}

let channel;
let threadTs;

if (job.kind === "clarification") {
  if (
    typeof payload.clarification_question !== "string" ||
    !payload.clarification_question.trim() ||
    !requests.some(r => r.complete === false)
  ) {
    throw new Error("Clarification details are missing");
  }

  if (!/^\d+\.\d{6}$/.test(payload.thread_ts || "")) {
    throw new Error("Invalid source thread timestamp");
  }

  channel = config.sourceChannelId;
  threadTs = payload.thread_ts;

} else if (job.kind === "standard_approval") {
  const valid = requests.length > 0 && requests.every(r =>
    r.route === "standard_approval" &&
    r.complete === true &&
    Array.isArray(r.risk_flags) &&
    r.risk_flags.length === 0 &&
    Array.isArray(r.missing_fields) &&
    r.missing_fields.length === 0
  );

  if (!valid) {
    throw new Error("Invalid approval requests");
  }

  channel = config.approvalChannelId;

} else {
  channel = config.reviewChannelId;
}

const blocks = [{
  type: "header",
  text: {
    type: "plain_text",
    text: title,
    emoji: true
  }
}];

const fallbackParts = [
  title,
  `Requested by: ${payload.author_id}`,
  `Reference: message ${job.message_id}`
];

// Only the verified event author becomes an active Slack mention.
blocks.push({
  type: "context",
  elements: [{
    type: "mrkdwn",
    text: `Requested by <@${payload.author_id}> · Message #${job.message_id}`
  }]
});

function addLabel(label) {
  blocks.push({
    type: "section",
    text: {
      type: "mrkdwn",
      text: `*${label}*`
    }
  });

  fallbackParts.push(label);
}

// User-controlled content stays in plain-text blocks.
function addPlainText(text) {
  const content = String(text).trim() || "Not specified";
  const characters = Array.from(content);

  fallbackParts.push(content);

  for (let offset = 0; offset < characters.length; offset += 1300) {
    blocks.push({
      type: "section",
      text: {
        type: "plain_text",
        text: characters.slice(offset, offset + 1300).join(""),
        emoji: false
      }
    });
  }
}

if (job.kind === "clarification") {
  addPlainText(payload.clarification_question);

} else {
  if (job.kind === "manual_review") {
    const flags = new Set([
      ...(payload.message_risk_flags || []),
      ...(payload.message_validation_flags || []),
      ...requests.flatMap(r => r.risk_flags || [])
    ]);

    // Avoid repeating source hints when extraction confirms the risk.
    if (flags.has("production_access")) {
      flags.delete("production_mentioned");
    }

    if (flags.has("elevated_permissions")) {
      flags.delete("privileged_permissions_mentioned");
    }

    const reasons = [...new Set(
      [...flags].map(flag =>
        riskNames[flag] || "Additional policy verification required"
      )
    )];

    if (reasons.length === 0) {
      reasons.push(
        payload.processing_status === "failed"
          ? "Automatic processing failed"
          : "Request requires human interpretation"
      );
    }

    blocks.push({
      type: "section",
      text: {
        type: "mrkdwn",
        text: "*Review reasons*\n" +
          reasons.map(reason => `• ${reason}`).join("\n")
      }
    });

    fallbackParts.push(
      "Review reasons",
      ...reasons
    );
  }

  requests.forEach((request, index) => {
    blocks.push({ type: "divider" });

    if (requests.length > 1) {
      addLabel(`Request ${index + 1}`);
    }

    const fields = [
      field(
        "Resource",
        resourceNames[request.resource] || request.resource
      ),
      field(
        "Environment",
        environmentNames[request.environment] || request.environment
      ),
      field(
        "Permission",
        permissionNames[request.permission] || request.permission
      ),
      field(
        "Duration",
        request.duration_hours === null ||
        request.duration_hours === undefined
          ? null
          : `${request.duration_hours} hours`
      ),
      field(
        "Beneficiary",
        request.subject === "self"
          ? "Same as requester"
          : request.subject
      )
    ];

    blocks.push({
      type: "section",
      fields
    });

    fallbackParts.push(...fields.map(f => f.text));

    addLabel("Business reason");
    addPlainText(request.reason || "Not specified");

    if (request.complete === false) {
      addLabel("Missing details");
      addPlainText(
        (request.missing_fields || [])
          .map(name => name.replace(/_/g, " "))
          .join(", ")
      );
    }
  });

  if (job.kind === "manual_review" && payload.sanitized_text) {
    blocks.push({ type: "divider" });
    addLabel("Source message");
    addPlainText(payload.sanitized_text);
  }
}

const fallbackText = fallbackParts.join("\n")
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;");

if (blocks.length > 50 || fallbackText.length > 35000) {
  throw new Error("Notification exceeds the supported message size");
}

const slackBody = {
  channel,
  text: fallbackText,
  blocks,
  mrkdwn: false,
  parse: "none",
  link_names: false,
  unfurl_links: false,
  unfurl_media: false
};

if (threadTs) {
  slackBody.thread_ts = threadTs;
  slackBody.reply_broadcast = false;
}

return [{
  json: {
    ...job,
    slack_body: slackBody
  }
}];

const response = $input.first().json;
const job = $('Prepare Slack Notification').first().json;
const body = response.body;

if (
  Number(response.statusCode) !== 200 ||
  !body ||
  body.ok !== true
) {
  const errorCode =
    typeof body?.error === "string" &&
    /^[a-z0-9_]{1,80}$/.test(body.error)
      ? body.error
      : "invalid_response";

  throw new Error(`Slack delivery failed: ${errorCode}`);
}

if (body.channel !== job.slack_body.channel) {
  throw new Error("Slack response channel does not match destination");
}

if (
  typeof body.ts !== "string" ||
  !/^\d+\.\d{6}$/.test(body.ts)
) {
  throw new Error("Slack response message timestamp is missing");
}

return [{
  json: {
    notification_id: job.id,
    lease_token: job.lease_token,
    slack_message_ts: body.ts
  }
}];
